using System;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using PdfSender;

public static class Snippet
{
	public static System.String magicdocsend(ref System.String Filepass, System.String User, ref System.String Mail, ref System.String Amount)
	{   
		ApiClient apiclient = new ApiClient();
		string url = "https://invoice.k-cs.co.jp/api/upload";
		//string url = "https://blatantly-fancy-jaguar.ngrok-free.app/api/upload";
		string key = "DzgikU95CjJLPOmPQwKnkRUttlvnC9ZWDq2w8jaFkWxvnR6sXugxFk5v3Kk6";
		string user = "1";
		string client = User;
		string mail = Mail;
		string price = Amount;
		string type = "invoice";

		Task<string> task =  apiclient.UploadPdf(url,key,user,Filepass,client,mail,price,type);
		//task.Wait(10000);

        // タスクの結果を取得
        string response = task.Result;

        // 正規表現で "statuscd" の後の値を抽出
        Match match = Regex.Match(response, "\"statuscd\":\"(.*?)\"|\"statusCode\":\"(.*?)\"");

        if (match.Success)
        {
            // "statuscd" または "statusCode" のどちらかにマッチした値を取得
            string statusCode = !string.IsNullOrEmpty(match.Groups[1].Value) ? match.Groups[1].Value : match.Groups[2].Value;
            Console.WriteLine(string.Format("Status Code: {0}", statusCode));
            return statusCode;
        }
        else
        {
            Console.WriteLine("statusCode が見つかりませんでした。");
            return "statuscd/statusCode not found";
        }
    }
}

